<template>
 <div class="app-container warehouse-control">
  <div class="intro"><div><h2>{{ transfer ? '跨实仓调拨' : '仓库库存对账' }}</h2><p>{{ transfer ? '同公司、同货主跨实仓移动商品。原批次、质量、单位及成本全程保留，在途单独跟踪。' : '按货主和实仓合并全部虚仓比较。先核查待入账单据，再处理真实盘盈盘亏。' }}</p></div><el-button v-hasPermi="[permission + ':create']" type="primary" @click="startCreate">{{ transfer ? '新增调拨' : '新建库存检查' }}</el-button></div>
  <el-alert :closable="false" type="info" :title="transfer ? '发出10件、收货8件：原仓实物减少10件，目的仓增加8件，剩余2件在途；在途不参与销售。' : '库存查询只生成快照。仓库实物数量 = 未冻结数量 + 冻结数量；缺失字段、查询失败和待入账不会当作缺货。'"/>
  <el-form inline size="small" class="filters" @submit.native.prevent="search"><el-form-item label="单号"><el-input v-model.trim="query.document_sn" clearable placeholder="完整单号可跨日期定位" @keyup.enter.native="search"/></el-form-item><el-form-item label="状态"><el-select v-model="query.state" clearable><el-option v-for="s in states" :key="s" :value="s" :label="label(s)"/></el-select></el-form-item><el-form-item label="创建日期"><el-date-picker v-model="dates" type="daterange" value-format="yyyy-MM-dd" start-placeholder="开始日期" end-placeholder="结束日期"/></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button><el-button v-if="!transfer" @click="openReports">仓库盘点通知</el-button></el-form-item></el-form>
  <el-table v-loading="loading" :data="rows" empty-text="暂无单据，默认查询近90天" size="small">
   <el-table-column label="单据 / 创建时间" min-width="300"><template slot-scope="{row}"><el-button type="text" @click="open(row.id)">{{ row.document_sn }}</el-button><div class="muted">{{ row.create_time }}</div></template></el-table-column>
   <el-table-column label="货主 / 仓库" min-width="250"><template slot-scope="{row}">{{ row.owner_code }}<div v-if="transfer">{{ warehouseName(row.source_store) }} → {{ warehouseName(row.target_store) }}</div><div v-else>{{ row.real_store }}<div class="muted">路由虚仓 {{ row.store_code }}，比较该实仓全部虚仓</div></div></template></el-table-column>
   <el-table-column :label="transfer ? '计划 / 已发 / 已收 / 在途' : '检查结果'" min-width="290"><template slot-scope="{row}"><template v-if="transfer"><div v-for="q in row.quantity_summary" :key="q.stock_unit">{{ q.quantity }} / {{ q.out_quantity }} / {{ q.in_quantity }} / <b>{{ q.transit_quantity }} {{ q.stock_unit }}</b></div><div v-for="e in row.executions" :key="e.id" class="muted">{{ side(e.side) }}：{{ label(e.dispatch_state) }}{{ e.receipt_final ? ' · 最终确认' : '' }}</div></template><template v-else><el-tag v-if="row.scope_mode==='FULL'" size="mini">全仓检查 · {{ row.coverage==='OMS_WMS_LIST'?'含仓库导入清单':'OMS清单覆盖' }}</el-tag><br v-if="row.scope_mode==='FULL'"/><span v-if="row.state==='COMPLETED'||row.state==='PARTIAL'">实物不符 <b :class="{danger:row.difference_count}">{{ row.difference_count }}</b> 行 · 待核查 {{ row.attention_count }} 行</span><span v-else>{{ label(row.state) }}</span><div class="muted">OMS {{ row.oms_snapshot_at || '—' }}<br>WMS {{ row.wms_snapshot_at || '—' }}</div></template></template></el-table-column>
   <el-table-column label="当前进度 / 异常" min-width="230"><template slot-scope="{row}"><el-tag size="small" :type="row.last_error?'danger':row.state==='COMPLETED'?'success':'info'">{{ label(row.state) }}</el-tag><div v-if="row.last_error" class="danger">{{ row.last_error }}</div></template></el-table-column><el-table-column label="操作" width="100"><template slot-scope="{row}"><el-button type="text" @click="open(row.id)">查看明细</el-button></template></el-table-column>
  </el-table><pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" :page-sizes="[20,50]" @pagination="load"/>

  <inventory-check-create :visible="!transfer&&creating" :warehouses="warehouses" :initial="form" @close="creating=false" @created="createdCheck"/>
  <el-dialog v-if="transfer" :title="transfer?'新增跨实仓调拨':'新建库存检查'" :visible.sync="creating" width="1000px" append-to-body :close-on-click-modal="false" custom-class="control-create">
   <el-form label-position="top"><h3>1. {{ transfer ? '选择出入库仓库' : '选择货主实仓范围' }}</h3><div class="two"><el-form-item :label="transfer?'出库虚仓':'查询路由虚仓'" required><el-select v-model="form.source_store" filterable @change="clearSources"><el-option v-for="w in warehouses" :key="w.store_code" :value="w.store_code" :label="optionLabel(w)"/></el-select></el-form-item><el-form-item v-if="transfer" label="目的虚仓" required><el-select v-model="form.target_store" filterable><el-option v-for="w in targets" :key="w.store_code" :value="w.store_code" :label="optionLabel(w)"/></el-select><p class="muted">只显示同货主其他实仓。调出须真实出库，调入须真实入库。</p></el-form-item><el-form-item v-else label="比较范围"><p>{{ rangeLabel }}</p><p class="muted">同货主、同实仓的虚仓只聚合比较一次。</p></el-form-item></div>
    <h3>2. {{ transfer?'选择原库存批次':'设置检查商品' }}</h3><el-form-item label="SKU编码" required><el-input v-model="form.skuText" type="textarea" :rows="2" placeholder="输入完整SKU，多个用换行或逗号分隔，每次最多100个" @input="sourceRows=[]"/></el-form-item>
    <template v-if="transfer"><el-button :loading="sourceLoading" @click="loadSources">查询可调批次</el-button><p class="muted">显示当前批次可用数量。审核时重新扣除订单预占、渠道承诺及福袋保障，防止抢占已承诺库存。</p><el-table :data="sourceRows" size="small" max-height="340"><el-table-column label="商品 / SKU" min-width="230"><template slot-scope="{row}">{{ row.goods_name }}<div class="muted">{{ row.sku_sn }}</div></template></el-table-column><el-table-column prop="batch_code" label="原批次" min-width="150"/><el-table-column label="质量 / 成本" width="130"><template slot-scope="{row}">{{ grade(row.inventory_type) }}<div>¥{{ money(row.unit_cost) }} / {{ row.stock_unit }}</div></template></el-table-column><el-table-column label="当前可用" width="110"><template slot-scope="{row}">{{ row.free }} {{ row.stock_unit }}</template></el-table-column><el-table-column label="本次调拨" width="180"><template slot-scope="{row}"><el-input-number v-model="row.quantity" :min="0" :max="Math.min(row.free,100000000)" :precision="0" size="small"/></template></el-table-column></el-table></template>
    <template v-else><el-form-item label="仓库查询方式"><el-radio-group v-model="form.method"><el-radio label="inventory.query">多商品检查</el-radio><el-radio label="stock.query">单SKU批次分页检查</el-radio></el-radio-group><p class="muted">多商品接口返回批次缺失时，改用批次分页检查；分页最多5000行，完整后才给出结果。</p></el-form-item><el-form-item v-if="form.method==='stock.query'" label="指定批次（可留空）"><el-input v-model.trim="form.batch_code" placeholder="留空检查该SKU全部批次"/></el-form-item></template>
    <el-form-item v-if="transfer" label="调拨原因" required><el-input v-model.trim="form.reason" type="textarea" maxlength="1000" show-word-limit/></el-form-item>
   </el-form><div slot="footer"><el-button @click="creating=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitCreate">{{ transfer?'保存待审核调拨':'提交库存检查' }}</el-button></div>
  </el-dialog>

  <el-drawer :visible.sync="showDetail" :title="transfer?'跨实仓调拨详情':'库存对账详情'" size="94%" append-to-body custom-class="control-detail" @closed="stopPolling">
   <div v-if="document" class="detail-body"><el-button v-if="transfer&&returnCheckId" type="text" @click="returnToCheck">返回来源库存检查</el-button><div class="doc-head"><div><h2>{{ document.document_sn }}</h2><p>{{ transfer?document.owner_code+' · '+warehouseName(document.source_store)+' → '+warehouseName(document.target_store):document.owner_code+' · '+document.real_store }}</p></div><el-tag :type="document.last_error?'danger':'info'">{{ label(document.state) }}</el-tag></div>
    <el-alert v-if="document.last_error" :title="document.last_error" type="error" :closable="false"/>
    <template v-if="transfer"><div class="metrics"><div v-for="metric in transferMetrics" :key="metric.key"><span>{{ metric.name }}</span><b>{{ quantities(document.lines,metric.key) }}</b></div></div><el-alert title="公司拥有数量 = 仓库实物 + 调拨在途。调拨在途不进入可用库存；目的仓按原批次、原质量和原成本入账。" type="info" :closable="false"/>
     <h3>商品与原批次</h3><el-table :data="document.lines" size="small"><el-table-column label="商品 / SKU" min-width="230"><template slot-scope="{row}">{{ row.goods_name }}<div class="muted">{{ row.sku_sn }}</div></template></el-table-column><el-table-column label="原批次 / 质量 / 成本" min-width="200"><template slot-scope="{row}">{{ row.batch_code }} · {{ grade(row.inventory_type) }}<div class="muted">¥{{ money(row.unit_cost) }} / {{ row.stock_unit }}</div></template></el-table-column><el-table-column v-for="m in transferMetrics" :key="m.key" :label="m.name" min-width="100"><template slot-scope="{row}">{{ row[m.key] }} {{ row.stock_unit }}</template></el-table-column></el-table>
     <h3>两侧仓库交互与实际物流</h3><div v-for="e in document.executions" :key="e.id" class="execution"><div class="doc-head"><div><b>{{ side(e.side) }} · {{ e.document_sn }}</b><p>{{ warehouseName(e.store_code) }} · 仓库单号 {{ e.external_order || '尚未返回' }}</p></div><div><el-tag :type="e.review_pending?'danger':'info'">{{ label(e.dispatch_state) }}{{ e.receipt_final?' · 最终确认':'' }}</el-tag><el-button v-hasPermi="['warehouse:transfer:queryWarehouse']" type="text" @click="doAction('query',{execution_id:e.id})">查询该侧仓单</el-button></div></div><p v-if="e.review_pending||e.last_error" class="danger">{{ e.last_error || '回传与原计划冲突，须取得仓库更正' }}</p><p>实际物流：{{ e.carrier_code || '仓库尚未回传' }} · {{ e.waybill || '暂无运单号' }}</p><p class="muted">{{ side(e.side) }}计划 {{ quantities(e.plan,'quantity') }}；{{ e.receipt_final?'最终确认已收到，实际数量见上方，短收仍保留在途。':'正在等待仓库实物回传。' }}</p><interaction-table :rows="e.interactions" @evidence="openEvidence"/></div>
     <h3>实物回传与库存入账</h3><el-table :data="document.events" size="small"><el-table-column prop="create_time" label="收到时间" min-width="165"/><el-table-column prop="message_id" label="仓库原消息" min-width="180"/><el-table-column label="实物明细" min-width="350"><template slot-scope="{row}"><div v-for="l in row.receipt.lines" :key="l.line_key">{{ l.sku_sn }} · {{ l.batch_code }} · {{ grade(l.inventory_type) }} · {{ l.quantity }}</div></template></el-table-column><el-table-column label="入账状态" min-width="160"><template slot-scope="{row}">{{ label(row.state) }}<div class="danger">{{ row.last_error }}</div></template></el-table-column><el-table-column label="证据" width="100"><template slot-scope="{row}"><el-button v-if="row.source_log_id" type="text" @click="openEvidence(row.source_log_id)">原始交互</el-button></template></el-table-column></el-table>
    </template>
    <inventory-check-results v-else-if="document.scope_mode==='FULL'" :document="document" @refresh="refresh" @snapshot="open"/>
    <template v-else><el-alert v-if="document.parent_id" title="这是全仓任务中的商品快照；调整前请重新检查最新库存。" type="info" :closable="false"/><el-button v-if="document.parent_id||document.source_check_id" type="text" @click="open(document.parent_id||document.source_check_id)">返回来源全仓检查</el-button><inventory-check-next-step v-if="document.result" :document="document" :can-adjust="!!canAdjust" :saving="pendingLoading" @pending="inspectPending" @recheck="recheck" @adjust="startAdjustment" @details="scrollCheckSection"/><div class="metrics"><div><span>实物不符</span><b :class="{danger:document.difference_count}">{{ document.difference_count }} 行</b></div><div><span>字段 / 冻结待核查</span><b>{{ document.attention_count }} 行</b></div><div><span>OMS快照</span><strong>{{ document.oms_snapshot_at || '等待检查' }}</strong></div><div><span>WMS响应接收时间</span><strong>{{ document.wms_snapshot_at || '等待检查' }}</strong></div></div><p class="muted">WMS时间是本次响应接收时间；查询不保证两边绝对同时。比较虚仓：{{ document.scope.stores.join('、') }}。库存变化后须重新检查。</p>
     <template v-if="document.result"><el-alert v-if="document.result.pending_documents.length" title="存在待确认或待入账单据，先核查下列单据，再重新检查库存。当前差额不会自动调整。" type="warning" :closable="false"/><el-table ref="checkPending" v-if="document.result.pending_documents.length" :data="document.result.pending_documents" size="small"><el-table-column prop="document_sn" label="待确认单据" min-width="320"/><el-table-column prop="reason" label="为什么等待" min-width="350"/><el-table-column label="下一步操作" width="150"><template slot-scope="{row}"><el-button v-if="isTransferPending(row)" v-hasPermi="['warehouse:transfer:query']" type="text" :loading="pendingLoading" @click="inspectPending(row)">查看调拨单</el-button><span v-else class="muted">按单号核查来源业务</span></template></el-table-column></el-table><h3>具体库存差异</h3><el-table :data="document.result.rows" size="small"><el-table-column label="SKU / 批次 / 质量" min-width="260"><template slot-scope="{row}">{{ row.sku_sn }}<div class="muted">{{ row.batch_code || '仓库未提供批次' }} · {{ grade(row.inventory_type) }} · {{ row.stock_unit || '库存单位待确认' }}</div></template></el-table-column><el-table-column label="OMS实物" width="105"><template slot-scope="{row}">{{ value(row.oms_physical) }}</template></el-table-column><el-table-column label="WMS实物" width="110"><template slot-scope="{row}">{{ value(row.wms_physical) }}</template></el-table-column><el-table-column label="实物差额" width="110"><template slot-scope="{row}"><b :class="{danger:row.difference}">{{ signed(row.difference) }}</b></template></el-table-column><el-table-column label="OMS业务占用 / WMS冻结" min-width="200"><template slot-scope="{row}">{{ value(row.oms_held) }} / {{ value(row.wms_frozen) }}<div class="muted">两项分别核查，不直接调整实物</div></template></el-table-column><el-table-column label="检查结论 / 下一步" min-width="270"><template slot-scope="{row}"><b>{{ label(row.status) }}</b><div class="muted">{{ advice(row.status) }}</div><div v-for="s in row.sources" :key="s.store_code">{{ s.store_code }}：实物 {{ s.physical }}，可用 {{ s.free }}</div></template></el-table-column></el-table></template>
     <h3 ref="checkAdjustments">独立差异调整申请</h3><p class="muted">只有实物差异、字段齐全且无待入账单据时才可申请。明确虚仓归属、原批次成本及盘点凭证；审核时再次校验整个范围的库存版本。</p><el-table :data="document.adjustments" size="small"><el-table-column prop="document_sn" label="调整单" min-width="300"/><el-table-column label="原因 / 凭证" min-width="250"><template slot-scope="{row}">{{ row.reason }}<div class="muted">{{ row.evidence }}</div></template></el-table-column><el-table-column label="申请 / 审核" min-width="150"><template slot-scope="{row}">{{ row.created_by }} / {{ row.reviewed_by || '待审核' }}</template></el-table-column><el-table-column label="状态 / 处理" min-width="280"><template slot-scope="{row}">{{ label(row.state) }}<p class="danger">{{ row.last_error }}</p><template v-if="row.state==='DRAFT'"><el-button v-hasPermi="['warehouse:reconciliation:review']" type="text" @click="reviewAdjustment(row,'APPROVE')">核对并审核入账</el-button><el-button v-hasPermi="['warehouse:reconciliation:review']" type="text" @click="reviewAdjustment(row,'REJECT')">驳回</el-button></template><el-button v-if="row.state==='APPROVED'" v-hasPermi="['warehouse:reconciliation:review']" type="text" @click="retryAdjustment(row)">重试原调整</el-button></template></el-table-column></el-table><h3 ref="checkInteractions">库存查询交互</h3><interaction-table :rows="document.interactions" @evidence="openEvidence"/>
    </template>
    <h3>人工处理记录</h3><el-table :data="document.audit || []" size="small" empty-text="暂无人工处理记录"><el-table-column prop="create_time" label="操作时间" width="170"/><el-table-column prop="actor" label="操作人" width="130"/><el-table-column label="动作" width="170"><template slot-scope="{row}">{{ auditLabel(row.action) }}</template></el-table-column><el-table-column prop="reason" label="业务原因 / 凭证" min-width="400"/></el-table>
   </div><div class="detail-footer"><span class="muted">{{ document ? label(document.state) : '' }}</span><div><template v-if="document&&transfer"><el-button v-if="document.state==='DRAFT'" v-hasPermi="['warehouse:transfer:approve']" type="primary" :loading="saving" @click="approveTransfer">审核并锁定原库存</el-button><el-button v-if="document.state!=='DRAFT'&&document.state!=='COMPLETED'" v-hasPermi="['warehouse:transfer:retry']" @click="doAction('retry')">重试待完成步骤</el-button><el-button v-if="['ACTIVE','STOPPING'].includes(document.state)" v-hasPermi="['warehouse:transfer:stop']" @click="stopTransfer">停止未出库剩余</el-button><el-button v-if="hasTransit" v-hasPermi="['warehouse:transfer:recover']" @click="startRecovery">安排在途收回原仓</el-button></template><template v-if="document&&!transfer&&document.scope_mode!=='FULL'"><el-button v-if="document.state==='FAILED'&&!document.parent_id" v-hasPermi="['warehouse:reconciliation:create']" @click="doAction('retry')">重试查询</el-button><el-button v-hasPermi="['warehouse:reconciliation:create']" @click="recheck">重新检查最新库存</el-button><el-button v-if="canAdjust" v-hasPermi="['warehouse:reconciliation:adjust']" type="primary" @click="startAdjustment">申请差异调整</el-button></template><el-button @click="refresh">刷新进度</el-button><el-button @click="showDetail=false">关闭</el-button></div></div>
  </el-drawer>

  <el-dialog :title="recovering?'安排独立收回原仓入库':'申请实物差异调整'" :visible.sync="adjusting" width="1080px" append-to-body :close-on-click-modal="false"><el-alert :closable="false" type="warning" :title="recovering?'两侧及已有收回仓单须最终确认；只按原行在途余额创建收回入库单，实际收回后才加回原仓。':'请核实真实盘盈盘亏、虚仓归属和成本。此申请须独立审核后才改变OMS库存。'"/><el-table :data="adjustForm.lines" size="small"><el-table-column label="SKU / 批次 / 质量" min-width="230"><template slot-scope="{row}">{{ row.sku_sn }}<div class="muted">{{ row.batch_code }} · {{ grade(row.inventory_type) }}</div></template></el-table-column><el-table-column v-if="!recovering" label="归属虚仓" min-width="170"><template slot-scope="{row}"><el-select v-model="row.store_code" size="small"><el-option v-for="s in document.scope.stores" :key="s" :value="s" :label="warehouseName(s)"/></el-select></template></el-table-column><el-table-column :label="recovering?'本次收回数量':'有符号调整量（盈+亏-）'" width="230"><template slot-scope="{row}"><el-input-number v-model="row.quantity" :precision="0" :min="recovering?0:-100000000" :max="recovering?row.maximum:100000000" size="small"/></template></el-table-column><el-table-column v-if="!recovering" label="原批次 / 盘盈单位成本" width="200"><template slot-scope="{row}"><el-input-number v-model="row.unit_cost" :min="0" :precision="2" size="small"/></template></el-table-column><el-table-column v-if="!recovering" label="分摊" width="80"><template slot-scope="{row}"><el-button type="text" @click="splitAdjustment(row)">拆分</el-button></template></el-table-column></el-table><el-form label-position="top"><el-form-item label="业务原因" required><el-input v-model.trim="adjustForm.reason" type="textarea" maxlength="1000"/></el-form-item><el-form-item v-if="!recovering" label="仓库盘点、成本及待入账核查凭证" required><el-input v-model.trim="adjustForm.evidence" type="textarea" maxlength="1000"/></el-form-item></el-form><div slot="footer"><el-button @click="adjusting=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitAdjustment">{{ recovering?'创建收回仓库单':'保存独立调整申请' }}</el-button></div></el-dialog>
  <el-dialog title="仓库盘点通知（仅留证，未自动改账）" :visible.sync="showReports" width="1100px" append-to-body><el-table :data="reportRows" size="small"><el-table-column prop="check_order" label="仓库盘点单" min-width="200"/><el-table-column label="仓库 / 货主" min-width="190"><template slot-scope="{row}">{{ row.warehouse_code }} / {{ row.owner_code }}</template></el-table-column><el-table-column label="盘点事实" min-width="400"><template slot-scope="{row}"><div v-for="(l,i) in row.report.lines" :key="i">{{ l.sku_sn }} · {{ l.batch_code || '未提供批次' }} · {{ l.inventory_type }}：变化 {{ signed(l.delta) }}，盘点总量 {{ value(l.total) }}</div><div class="muted">第 {{ row.report.page }} / {{ row.report.pages }} 页 · {{ row.message_id }}</div></template></el-table-column><el-table-column prop="create_time" label="收到时间" width="170"/></el-table></el-dialog>
  <el-dialog title="仓库交互证据" :visible.sync="showEvidence" width="1000px" append-to-body><p class="muted">{{ evidence.action }} · {{ evidence.result }} · {{ evidence.error_info }}</p><pre>{{ evidence.request_body || '当前权限未返回原报文' }}</pre><pre>{{ evidence.response_body || '暂无响应报文' }}</pre></el-dialog>
 </div>
