const InteractionTable={props:{rows:{type:Array,default:()=>[]}},render(h){return h('el-table',{props:{data:this.rows,size:'mini'}},[h('el-table-column',{props:{prop:'create_time',label:'交互时间',minWidth:170}}),h('el-table-column',{props:{label:'动作',minWidth:160},scopedSlots:{default:({row})=>actionLabels[row.action]||row.action}}),h('el-table-column',{props:{label:'交互结果',width:110},scopedSlots:{default:({row})=>resultLabels[row.result]||row.result}}),h('el-table-column',{props:{prop:'error_info',label:'说明',minWidth:220}}),h('el-table-column',{props:{label:'证据',width:100},scopedSlots:{default:({row})=>h('el-button',{props:{type:'text'},on:{click:()=>this.$emit('evidence',row.id)}},'查看交互')}})])}}
export default {components:{InteractionTable,InventoryCheckCreate,InventoryCheckResults,InventoryCheckNextStep},data:()=>({rows:[],total:0,query:defaults(),dates:[],loading:false,sequence:0,warehouses:[],creating:false,form:{},sourceRows:[],sourceLoading:false,sourceSequence:0,saving:false,pendingLoading:false,showDetail:false,document:null,detailSequence:0,pollTimer:null,pollCount:0,adjusting:false,recovering:false,adjustForm:{lines:[]},showReports:false,reportRows:[],showEvidence:false,evidence:{},transferMetrics:[{key:'quantity',name:'计划'},{key:'out_quantity',name:'已发出'},{key:'in_quantity',name:'目的已入库'},{key:'transit_quantity',name:'仍在途'},{key:'recovered_quantity',name:'原仓已收回'},{key:'released_quantity',name:'未出库已释放'}]}),computed:{returnCheckId(){const id=String(this.$route.query.return_check_id||'');return /^[1-9]\d{0,17}$/.test(id)?id:''},transfer(){return this.$route.path.includes('warehouseTransfers')},kind(){return this.transfer?'transfers':'reconciliations'},permission(){return 'warehouse:'+(this.transfer?'transfer':'reconciliation')},states(){return this.transfer?['DRAFT','ACTIVE','STOPPING','STOPPED','COMPLETED']:['PENDING','RUNNING','STOPPING','STOPPED','PARTIAL','COMPLETED','FAILED']},targets(){const s=this.warehouses.find(w=>w.store_code===this.form.source_store);return s?this.warehouses.filter(w=>w.owner_code===s.owner_code&&w.real_store_code!==s.real_store_code&&Number(w.inbound_mode)===1):[]},rangeLabel(){const s=this.warehouses.find(w=>w.store_code===this.form.source_store);return s?this.warehouses.filter(w=>w.owner_code===s.owner_code&&w.real_store_code===s.real_store_code).map(w=>w.store_code).join('、'):'选择路由虚仓后显示'},hasTransit(){return this.document&&this.document.lines&&this.document.lines.some(l=>Number(l.transit_quantity)>0)},canAdjust(){return this.document&&!this.document.parent_id&&this.document.scope_mode!=='FULL'&&this.document.result&&this.document.result.can_adjust&&!this.document.adjustments.length}},watch:{'$route.path'(){this.showDetail=false;this.stopPolling();this.reset();if(this.$route.query.id)this.open(this.$route.query.id)},'$route.query.id'(id){if(id)this.open(id)}},async created(){this.query.document_sn=String(this.$route.query.document_sn||'').slice(0,64);this.load();try{this.warehouses=(await api.options()).data||[]}catch(_){}if(this.$route.query.id)this.open(this.$route.query.id)},beforeDestroy(){this.sequence++;this.detailSequence++;this.stopPolling()},methods:{isTransferPending:isTransferCheckDocument,scrollCheckSection(section){const refs={pending:'checkPending',adjustments:'checkAdjustments',interactions:'checkInteractions'},target=this.$refs[refs[section]],element=target&&(target.$el||target);if(element)element.scrollIntoView({behavior:'smooth',block:'start'})},async inspectPending(row){if(!isTransferCheckDocument(row)||!this.document||this.pendingLoading)return;const checkId=this.document.id;this.pendingLoading=true;try{const r=(await api.list('transfers',{document_sn:row.document_sn,pageNum:1,pageSize:20})).data;if(!this.showDetail||!this.document||this.document.id!==checkId)return;if(!r||Number(r.total)!==1||!r.rows.length)return this.$message.warning('未找到当前公司对应调拨单，请核对单号和查询权限');await this.$router.push({path:'/oms-supplychain/warehouseTransfers',query:{id:String(r.rows[0].id),return_check_id:String(checkId)}})}finally{this.pendingLoading=false}},returnToCheck(){if(this.returnCheckId)this.$router.push({path:'/oms-supplychain/warehouseReconciliation',query:{id:this.returnCheckId}})},label(v){if(!this.transfer&&v==='STOPPING')return '等待当前商品结束';if(!this.transfer&&v==='STOPPED')return '已停止，可继续';return v==='COMPLETED'&&!this.transfer?'检查完成':labels[v]||v||'—'},auditLabel(s){return {stop:'停止检查',resume:'继续未查商品',retryFailed:'重试失败商品',CREATE:this.transfer?'创建草稿':'创建库存检查',APPROVE:'审核调拨',STOP:'停止未出库剩余',RETRY:'重试待完成步骤',RECOVER_CREATE:'安排独立收回',ADJUSTMENT_CREATE:'创建差异调整',ADJUSTMENT_APPROVE:'审核差异调整',ADJUSTMENT_REJECT:'驳回差异调整'}[s]||s},side(s){return {OUT:'原仓出库',IN:'目的仓收货',RECOVER:'独立收回原仓'}[s]||s},grade(s){return {ZP:'正品',CP:'次品',CC:'次品'}[s]||s||'待确认'},value(v){return v==null?'未提供':v},signed(v){return v==null?'待核查':Number(v)>0?'+'+v:String(v)},money(v){return Number(v||0).toFixed(2)},warehouseName(code){const w=this.warehouses.find(w=>w.store_code===code);return w?w.store_name+' · '+code:code},optionLabel(w){return w.store_name+' · '+w.store_code+' / '+w.owner_code+' / '+w.real_name},quantities(lines,key){const result={};(lines||[]).forEach(l=>{const unit=l.stock_unit||'件';result[unit]=(result[unit]||0)+Number(l[key]||0)});return Object.entries(result).map(([u,q])=>q+' '+u).join(' + ')||'0'},advice(s){return {MATCHED:'本次快照一致，后续业务仍按实时库存处理',PHYSICAL_DIFFERENCE:'核对盘点和实际虚仓归属后申请独立调整',FROZEN_CHECK:'核查仓库冻结与OMS订单、调拨、质量占用来源',MISSING_WMS:'核对仓库查询范围和返回完整性；缺失不等于0',MISSING_FIELDS:'请仓库补齐未冻结及冻结数量后重新检查',MISSING_BATCH:'改用单SKU批次分页检查，取得批次后再调整',UNSUPPORTED_TYPE:'不能把机损、箱损、冻结等静默归入正次品',WAITING_POST:'先核查待确认或待入账单据，再检查最新库存'}[s]},search(){this.query.pageNum=1;this.load()},reset(){this.query=defaults();this.dates=[];this.load()},async load(){const seq=++this.sequence;this.loading=true;try{const r=(await api.list(this.kind,{...this.query,from:this.dates&&this.dates[0]||'',to:this.dates&&this.dates[1]||''})).data;if(seq===this.sequence){this.rows=r.rows||[];this.total=Number(r.total)}}finally{if(seq===this.sequence)this.loading=false}},key(){return 'WC_'+Date.now()+'_'+Math.random().toString(36).slice(2)},startCreate(){this.form={request_key:this.key(),scope_mode:'FULL',source_store:'',target_store:'',skuText:'',reason:'',method:'stock.query',batch_code:''};this.sourceRows=[];this.creating=true},clearSources(){this.sourceSequence++;this.sourceRows=[];this.form.target_store=''},skuList(){return [...new Set(String(this.form.skuText||'').split(/[\s,，;；]+/).filter(Boolean))]},async loadSources(){if(!this.form.source_store||!this.skuList().length)return this.$message.warning('请选择出库仓并填写完整SKU');const seq=++this.sourceSequence,store=this.form.source_store,skus=this.skuList().join("\n");this.sourceLoading=true;try{const d=(await api.sources({store_code:store,skus:this.skuList()})).data;if(seq!==this.sourceSequence||store!==this.form.source_store||skus!==this.skuList().join("\n"))return;this.sourceRows=[];(d.batches||[]).forEach(b=>['ZP','CP'].forEach(type=>{const free=Number(b[type==='ZP'?'zp_available_number':'cp_available_number']);if(free>0){const g=d.goods[b.sku_sn]||{};this.sourceRows.push({source_batch_id:b.id,sku_sn:b.sku_sn,goods_name:g.goods_name,batch_code:b.batch_code,inventory_type:type,unit_cost:b.transaction_price,stock_unit:g.stock_unit==='套'?'套':'件',free,quantity:0})}}))}finally{if(seq===this.sourceSequence)this.sourceLoading=false}},async submitCreate(){const skus=this.skuList();if(!this.form.source_store||!skus.length||skus.length>100)return this.$message.warning('请选择仓库，填写1至100个SKU');let body;if(this.transfer){const lines=this.sourceRows.filter(l=>Number(l.quantity)>0).map(l=>({source_batch_id:l.source_batch_id,sku_sn:l.sku_sn,inventory_type:l.inventory_type,quantity:l.quantity}));if(!this.form.target_store||!lines.length||!this.form.reason)return this.$message.warning('请选择目的仓、原批次数量并填写原因');body={request_key:this.form.request_key,source_store:this.form.source_store,target_store:this.form.target_store,reason:this.form.reason,lines}}else{if(this.form.method==='stock.query'&&skus.length!==1)return this.$message.warning('批次分页检查每次填写一个SKU');body={request_key:this.form.request_key,store_code:this.form.source_store,skus,method:this.form.method,batch_code:this.form.batch_code}}this.saving=true;try{const id=(await api.create(this.kind,body)).data;this.creating=false;this.load();await this.open(id)}finally{this.saving=false}},async createdCheck(id){this.creating=false;this.load();await this.open(id)},async open(id){this.stopPolling();this.document=null;this.showDetail=true;this.pollCount=0;await this.fetchDetail(id);this.schedulePoll()},async fetchDetail(id){const seq=++this.detailSequence;const d=(await api.detail(this.kind,id)).data;if(seq===this.detailSequence&&this.showDetail)this.document=d},async refresh(){if(!this.document)return;await this.fetchDetail(this.document.id);this.load();this.schedulePoll()},stopPolling(){clearTimeout(this.pollTimer);this.pollTimer=null},schedulePoll(){this.stopPolling();if(!this.showDetail||!this.document||this.pollCount>=1200)return;const d=this.document,pending=this.transfer?d.state==='STOPPING'||d.stock_state==='UNHELD'&&d.state==='ACTIVE'||(d.events||[]).some(e=>e.state==='PENDING')||(d.executions||[]).some(e=>e.dispatch_state==='SENDING'):['PENDING','RUNNING','STOPPING'].includes(d.state)||(d.adjustments||[]).some(a=>a.state==='APPROVED'&&!a.last_error);if(pending)this.pollTimer=setTimeout(async()=>{this.pollCount++;try{await this.fetchDetail(d.id)}finally{this.schedulePoll()}},3000)},async doAction(operation,extra={}){if(!this.document)return;this.saving=true;try{await api.action(this.kind,this.document.id,operation,{control_version:this.document.control_version,...extra});await this.refresh()}finally{this.saving=false}},async approveTransfer(){try{await this.$confirm('审核后锁定原批次可调库存，并自动下发调出仓。出库后形成在途，目的仓实收后入库。','审核调拨',{type:'warning'});await this.doAction('approve')}catch(_){}},async stopTransfer(){try{const r=await this.$prompt('停止须等待原仓明确确认；仅释放未出库部分，已出库仍在途。请填写原因。','停止未出库剩余',{inputValidator:v=>!!String(v||'').trim()||'请填写原因'});await this.doAction('stop',{reason:r.value})}catch(_){}},async recheck(){const d=this.document;this.form={request_key:this.key(),scope_mode:'SELECTED',source_store:d.store_code,target_store:'',skuText:d.scope.skus.join('\n'),reason:'',method:d.method,batch_code:d.scope.batch_code||''};this.creating=true},startAdjustment(){this.recovering=false;const d=this.document;this.adjustForm={request_key:this.key(),reason:'',evidence:'',lines:d.result.rows.filter(r=>Number(r.difference)!==0&&r.difference!=null).map(r=>({sku_sn:r.sku_sn,batch_code:r.batch_code,inventory_type:r.inventory_type,store_code:r.sources.length===1?r.sources[0].store_code:'',quantity:r.di